    long long limit = a[maxIndex - 1] - 500;
    int prefixLength =
        upper_bound(a.begin(), a.end(), limit) - a.begin();

    // 统计前缀中的已通过题目数量
    int passedCount = 0;

    for (int problem : passed) {
        if (problem <= prefixLength) {
            passedCount++;
        }
    }

    // 前缀没有全部通过，则违反规则一
    return passedCount < prefixLength;
}

